from typing import Any, Callable
import warnings
from functools import wraps
from langwatch.telemetry.tracing import LangWatchTrace, LangWatchSpan
from langwatch.telemetry.context import get_current_span as gcs, get_current_trace as gct

def _deprecated(func: Callable[[], Any]) -> Callable[[], Any]:
    @wraps(func)
    def wrapper(*args: Any, **kwargs: Any) -> Any:
        warnings.warn(
            f"{func.__name__} is deprecated. Use langwatch.telemetry instead.",
            DeprecationWarning, stacklevel=2,
        )
        return func(*args, **kwargs)
    return wrapper

@_deprecated
def get_current_span():
    return gcs()

@_deprecated
def get_current_trace():
    return gct()

warnings.warn(
    "ContextSpan and ContextTrace are deprecated. Use LangWatchSpan from langwatch.telemetry.span and LangWatchTrace from langwatch.telemetry.tracing instead.",
    DeprecationWarning,
    stacklevel=2,
)

ContextSpan = LangWatchSpan
ContextTrace = LangWatchTrace

import asyncio
import threading
from typing import TYPE_CHECKING, Dict, List
import contextvars
import warnings
from opentelemetry import trace as trace_api
from opentelemetry import context

from langwatch.utils.initialization import ensure_setup

if TYPE_CHECKING:
    from langwatch.telemetry.span import LangWatchSpan
    from langwatch.telemetry.tracing import LangWatchTrace

stored_langwatch_trace = contextvars.ContextVar["LangWatchTrace"](
    "stored_langwatch_trace"
)
main_thread_langwatch_trace: List["LangWatchTrace"] = []

stored_langwatch_span = contextvars.ContextVar["LangWatchSpan"]("stored_langwatch_span")
main_thread_langwatch_span: List["LangWatchSpan"] = []


def get_current_trace(
    suppress_warning: bool = False, start_if_none: bool = False
) -> "LangWatchTrace":
    """Get the current trace from the LangWatch context.

    Returns:
        A LangWatchTrace.
    """
    ensure_setup()
    trace = stored_langwatch_trace.get(None)
    if trace is not None:
        return trace

    if (
        _is_on_child_thread()
        and not _is_on_async_loop()
        and len(main_thread_langwatch_trace) > 0
    ):
        return main_thread_langwatch_trace[-1]

    from langwatch.telemetry.tracing import LangWatchTrace

    if not suppress_warning:
        warnings.warn(
            "No trace in context when calling langwatch.get_current_trace(), perhaps you forgot to use @langwatch.trace()?",
        )

    trace = LangWatchTrace()
    if start_if_none:
        otel_span = trace_api.get_current_span()
        otel_span_id = otel_span.get_span_context().span_id
        trace.__enter__()

        # Keep the previous span in the context if we are starting a new trace not at root level
        if otel_span_id != 0:
            ctx = trace_api.set_span_in_context(otel_span)
            context.attach(ctx)
        otel_span = trace_api.get_current_span()

        trace.__exit__(None, None, None)

        return trace
    return trace


def get_current_span() -> "LangWatchSpan":
    """Get the current span from the LangWatch context.
    If no span exists in LangWatch context, falls back to OpenTelemetry context.

    Returns:
        A LangWatchSpan.
    """
    ensure_setup()

    otel_span = trace_api.get_current_span()
    otel_span_id = otel_span.get_span_context().span_id

    # If on a child thread and there is no parent, try to find a parent from the main thread
    if (
        _is_on_child_thread()
        and not _is_on_async_loop()
        and len(main_thread_langwatch_span) > 0
        and otel_span_id == 0
    ):
        return main_thread_langwatch_span[-1]

    from langwatch.telemetry.span import LangWatchSpan

    trace = get_current_trace()
    return LangWatchSpan.wrap_otel_span(otel_span, trace)


def _set_current_trace(trace: "LangWatchTrace"):
    global main_thread_langwatch_trace
    # Only touch the main-thread global fallback in the pure-threading path.
    # In async mode, every asyncio.Task gets its own contextvar copy; the
    # shared list would leak traces between concurrent sibling tasks.
    if not _is_on_child_thread() and not _is_on_async_loop():
        main_thread_langwatch_trace.append(trace)

    try:
        return stored_langwatch_trace.set(trace)
    except Exception as e:
        warnings.warn(f"Failed to set LangWatch trace context: {e}")
        return None


def _set_current_span(span: "LangWatchSpan"):
    global main_thread_langwatch_span
    if not _is_on_child_thread() and not _is_on_async_loop():
        main_thread_langwatch_span.append(span)

    # Dummy token, just for the main thread span list
    return "token"


def _reset_current_trace(token: contextvars.Token):
    global main_thread_langwatch_trace
    if not _is_on_child_thread() and not _is_on_async_loop():
        if len(main_thread_langwatch_trace) > 0:
            main_thread_langwatch_trace.pop()

    try:
        stored_langwatch_trace.reset(token)
    except Exception as e:
        # Only warn if it's not a context error
        if "different Context" not in str(e):
            warnings.warn(f"Failed to reset LangWatch trace context: {e}")


def _reset_current_span(_token: str):
    global main_thread_langwatch_span
    if not _is_on_child_thread() and not _is_on_async_loop():
        if len(main_thread_langwatch_span) > 0:
            main_thread_langwatch_span.pop()


def _is_on_child_thread() -> bool:
    return threading.current_thread() != threading.main_thread()


def _is_on_async_loop() -> bool:
    """True when called from inside a running asyncio event loop.

    In async mode, ``asyncio.Task`` copies contextvars per task, so the
    ``main_thread_langwatch_*`` global fallbacks are both redundant and
    dangerous — two sibling tasks on the same thread would pollute each
    other via the shared list.
    """
    try:
        asyncio.get_running_loop()
        return True
    except RuntimeError:
        return False

"""Module for storing global state."""

import os
from typing import Optional
from .types import LangWatchClientProtocol

# Singleton instance of the client
__instance: Optional[LangWatchClientProtocol] = None

def get_instance() -> Optional[LangWatchClientProtocol]:
    """Get the current LangWatch client instance."""
    return __instance

def set_instance(client: LangWatchClientProtocol) -> None:
    """Set the current LangWatch client instance."""
    global __instance
    __instance = client

def get_endpoint() -> str:
    """Get the current endpoint URL of the LangWatch client."""
    if __instance is None:
        return os.getenv("LANGWATCH_ENDPOINT") or "REDACTED"
    return __instance.endpoint_url

def get_api_key() -> str:
    """Get the current API key of the LangWatch client."""
    if __instance is None:
        return os.getenv("LANGWATCH_API_KEY", "")
    return __instance.api_key

def set_api_key(api_key: str) -> None:
    """Set the current API key of the LangWatch client."""
    instance = get_instance()
    if instance is None:
        raise RuntimeError("LangWatch client has not been initialized. Call setup() first.")
    instance.api_key = api_key

